CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', theme text NOT NULL DEFAULT 'dark', saved_articles jsonb NOT NULL DEFAULT '[]', revision integer NOT NULL DEFAULT 0, ai_block jsonb);
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_field_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name','Engineer')); RETURN NEW; END $$;
CREATE TRIGGER create_field_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_field_profile();
CREATE TABLE public.incidents (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.incidents TO authenticated; GRANT ALL ON public.incidents TO service_role;
ALTER TABLE public.incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_incidents ON public.incidents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.ai_analyses (user_id uuid NOT NULL, incident_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,incident_id), FOREIGN KEY(user_id,incident_id) REFERENCES public.incidents(user_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ai_analyses TO authenticated; GRANT ALL ON public.ai_analyses TO service_role;
ALTER TABLE public.ai_analyses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_analyses ON public.ai_analyses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.diagnostic_checklists (user_id uuid NOT NULL, incident_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,incident_id), FOREIGN KEY(user_id,incident_id) REFERENCES public.incidents(user_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.diagnostic_checklists TO authenticated; GRANT ALL ON public.diagnostic_checklists TO service_role;
ALTER TABLE public.diagnostic_checklists ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_checklists ON public.diagnostic_checklists FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.intervention_reports (user_id uuid NOT NULL, id text NOT NULL, incident_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,incident_id) REFERENCES public.incidents(user_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.intervention_reports TO authenticated; GRANT ALL ON public.intervention_reports TO service_role;
ALTER TABLE public.intervention_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reports ON public.intervention_reports FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.incident_history (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.incident_history TO authenticated; GRANT ALL ON public.incident_history TO service_role;
ALTER TABLE public.incident_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_history ON public.incident_history FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.conversations (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_conversations ON public.conversations FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.read_field_workspace() RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('incidents',coalesce((select jsonb_agg(payload order by payload->>'date' desc) from incidents where user_id=auth.uid()),'[]'),'analyses',coalesce((select jsonb_object_agg(incident_id,payload) from ai_analyses where user_id=auth.uid()),'{}'),'stepsByIncident',coalesce((select jsonb_object_agg(incident_id,payload) from diagnostic_checklists where user_id=auth.uid()),'{}'),'documents',coalesce((select jsonb_agg(payload) from intervention_reports where user_id=auth.uid()),'[]'),'activities',coalesce((select jsonb_agg(payload order by payload->>'time' desc) from incident_history where user_id=auth.uid()),'[]'),'threads',coalesce((select jsonb_agg(payload) from conversations where user_id=auth.uid()),'[]'),'engineer',display_name,'theme',theme,'savedArticles',saved_articles,'revision',revision) FROM profiles WHERE id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.read_field_workspace() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.read_field_workspace() TO authenticated;
CREATE FUNCTION public.save_field_workspace(snapshot jsonb, expected_revision integer) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); rev integer; item jsonb; entry record; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
SELECT revision INTO rev FROM profiles WHERE id=uid FOR UPDATE;
IF rev IS NULL OR rev<>expected_revision THEN RAISE EXCEPTION 'Workspace changed in another tab. Reload before saving.'; END IF;
DELETE FROM intervention_reports WHERE user_id=uid;
DELETE FROM ai_analyses WHERE user_id=uid;
DELETE FROM diagnostic_checklists WHERE user_id=uid;
DELETE FROM incidents WHERE user_id=uid AND id NOT IN (SELECT value->>'id' FROM jsonb_array_elements(snapshot->'incidents'));
FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'incidents') LOOP INSERT INTO incidents(user_id,id,payload) VALUES(uid,item->>'id',item) ON CONFLICT(user_id,id) DO UPDATE SET payload=excluded.payload; END LOOP;
FOR entry IN SELECT * FROM jsonb_each(snapshot->'analyses') LOOP INSERT INTO ai_analyses VALUES(uid,entry.key,entry.value); END LOOP;
FOR entry IN SELECT * FROM jsonb_each(snapshot->'stepsByIncident') LOOP INSERT INTO diagnostic_checklists VALUES(uid,entry.key,entry.value); END LOOP;
FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'documents') LOOP INSERT INTO intervention_reports VALUES(uid,item->>'id',item->>'incidentId',item); END LOOP;
DELETE FROM incident_history WHERE user_id=uid;
FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'activities') LOOP INSERT INTO incident_history VALUES(uid,item->>'id',item); END LOOP;
DELETE FROM conversations WHERE user_id=uid;
FOR item IN SELECT value FROM jsonb_array_elements(snapshot->'threads') LOOP INSERT INTO conversations VALUES(uid,item->>'id',item); END LOOP;
UPDATE profiles SET display_name=snapshot->>'engineer',theme=snapshot->>'theme',saved_articles=snapshot->'savedArticles',revision=rev+1 WHERE id=uid;
RETURN rev+1; END $$;
REVOKE ALL ON FUNCTION public.save_field_workspace(jsonb,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_field_workspace(jsonb,integer) TO authenticated;